SELECT p.gender, CAST(p.dod AS FLOAT) / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS mortality_rate, a.icu, a.los, COUNT(DIAGNOSES_ICD.icd_code) AS comorbidity_count, AVG(a.los) AS average_length_of_stay, SUM(CASE WHEN d.itemid = '155297' THEN 1 ELSE 0 END) AS ckd_count, SUM(CASE WHEN d.itemid = '155297' THEN 1 ELSE 0 END) / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS ckd_prevalence, SUM(CASE WHEN d.itemid = '155297' THEN 1 ELSE 0 END) / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS diabetes_prevalence FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN chartevents c ON a.subject_id = c.subject_id AND a.hadm_id = c.hadm_id JOIN datetimesevents d ON a.subject_id = d.subject_id AND a.hadm_id = d.hadm_id WHERE p.gender = 'F' AND EXTRACT(YEAR FROM age(CURRENT_DATE, p.dob)) BETWEEN 83 AND 93 AND c.itemid = '480255' AND d.itemid IN ('155297', '480255') GROUP BY p.gender, a.icu, a.los;